UPDATE sys_menu SET parent_id = #{menu.parentId}, menu_name = #{menu.menuName},
    menu_type = #{menu.menuType}, route_name = #{menu.routeName}, path = #{menu.path},
    component = #{menu.component}, icon = #{menu.icon}, permission_id = #{menu.permissionId},
    sort_order = #{menu.sortOrder}, is_visible = #{menu.isVisible}, keep_alive = #{menu.keepAlive},
    status = #{menu.status}
WHERE menu_id = #{menu.menuId}
